import{_ as d,C as r,o as i,c as o,a3 as a,E as h}from"./chunks/framework.Ba39LDvt.js";const f=JSON.parse('{"title":"模拟电路自学","description":"从微电子基础、Razavi 课程与 SPICE 实践走向模拟 CMOS、ADC、PLL 和 gm/Id 设计。","frontmatter":{"title":"模拟电路自学","description":"从微电子基础、Razavi 课程与 SPICE 实践走向模拟 CMOS、ADC、PLL 和 gm/Id 设计。"},"headers":[],"relativePath":"self-learning/analog.md","filePath":"self-learning/analog.md","lastUpdated":1795513256000}'),n={name:"self-learning/analog.md"};function s(l,t,c,u,g,b){const e=r("CourseTable");return i(),o("div",null,[t[0]||(t[0]=a('<h1 id="模拟电路自学" tabindex="-1">模拟电路自学 <a class="header-anchor" href="#模拟电路自学" aria-label="Permalink to &quot;模拟电路自学&quot;">​</a></h1><p>模拟电路的主线是<strong>建立模型 → 手算预估 → 仿真检查 → 解释偏差 → 重新设计</strong>。一开始应能说明器件工作区和信号路径，而不是靠扫描尺寸碰出一条好看的曲线。可结合 <a href="/shanghaitech-ic-wiki-dev.github.io/map/analog">模拟学习地图</a> 与 <a href="/shanghaitech-ic-wiki-dev.github.io/research/analog-mixed">模拟及混合信号方向</a> 选择后续主题。</p><h2 id="入门-器件模型与基本放大器" tabindex="-1">入门：器件模型与基本放大器 <a class="header-anchor" href="#入门-器件模型与基本放大器" aria-label="Permalink to &quot;入门：器件模型与基本放大器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td>Razavi《Fundamentals of Microelectronics》</td><td>教材</td><td>入门</td><td>从二极管、BJT、MOS 到基本放大电路，适合电路基础之后学习</td></tr><tr><td>Razavi 微电子与模拟电路公开讲授（<a href="https://www.seas.ucla.edu/brweb/" target="_blank" rel="noreferrer">UCLA CCL</a>）</td><td>课程与作者资源入口</td><td>入门—进阶</td><td>配合作者教材查找公开课程，视频用于建立直觉，推导与习题仍需独立完成</td></tr><tr><td>Sedra、Smith 等《Microelectronic Circuits》</td><td>教材</td><td>入门—进阶</td><td>覆盖面广，可作为第二种解释；不要因符号不同误判模型矛盾</td></tr><tr><td><a href="https://ngspice.sourceforge.io/" target="_blank" rel="noreferrer">ngspice</a></td><td>电路仿真器</td><td>入门—进阶</td><td>先用简单网表学习直流工作点、交流小信号和瞬态分析</td></tr></tbody></table><p>先把共源、源跟随器、差分对和电流镜讲清楚。每次手算都写明忽略了什么，例如沟道长度调制、体效应或寄生电容；仿真前估算增益、摆幅与功耗数量级。结果不符时先查工作点和单位，再讨论高阶模型，不要直接改器件尺寸掩盖问题。</p><h2 id="进阶-cmos-设计与系统模块" tabindex="-1">进阶：CMOS 设计与系统模块 <a class="header-anchor" href="#进阶-cmos-设计与系统模块" aria-label="Permalink to &quot;进阶：CMOS 设计与系统模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td>Razavi《Design of Analog CMOS Integrated Circuits》</td><td>教材</td><td>进阶</td><td>学习噪声、频率响应、反馈、稳定性和运放设计，宜已有 MOS 小信号基础</td></tr><tr><td>Gray、Hurst、Lewis、Meyer《Analysis and Design of Analog Integrated Circuits》</td><td>教材</td><td>进阶—深入</td><td>训练更系统的分析，适合对照器件模型、反馈与噪声推导</td></tr><tr><td>Allen、Holberg《CMOS Analog Circuit Design》</td><td>教材</td><td>进阶</td><td>从电路规格到尺寸设计，关注设计流程及实际约束</td></tr><tr><td>Razavi《RF Microelectronics》</td><td>射频教材</td><td>进阶—深入</td><td>进入低噪声放大器、混频器、振荡器前，先补阻抗、噪声与非线性基础</td></tr><tr><td>Jespers、Murmann《Systematic Design of Analog CMOS Circuits》</td><td>方法教材</td><td>进阶</td><td>学习跨导效率（gm/Id）与查表设计，连接性能指标、器件尺寸和偏置</td></tr><tr><td>数据转换器与锁相环专题</td><td>模块路线</td><td>进阶—深入</td><td>ADC 先学采样、量化与比较器；PLL 先学反馈、相位模型与环路动态</td></tr></tbody></table><p>gm/Id 不是脱离工艺的通用尺寸公式。查表数据依赖 PDK、器件类型、沟道长度、偏置和温度，不能直接混用不同工艺的曲线。学习 ADC 可先建立理想量化器，再加入有限建立、噪声与失配；学习锁相环（Phase-Locked Loop，PLL）可先做行为模型，理解带宽、稳定性和噪声传递，再进入晶体管级。</p><h2 id="实践-用一个完整设计训练判断力" tabindex="-1">实践：用一个完整设计训练判断力 <a class="header-anchor" href="#实践-用一个完整设计训练判断力" aria-label="Permalink to &quot;实践：用一个完整设计训练判断力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/eda/open-source">Xschem 与开源模拟流程</a></td><td>原理图、SPICE 实验</td><td>入门—进阶</td><td>用开放工具和匹配的器件模型做小规模设计</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/eda/commercial">商用模拟工具链</a></td><td>Virtuoso、Spectre、HSPICE 导航</td><td>进阶</td><td>有授权和课程环境时使用；工具本身不能替代电路分析</td></tr><tr><td>两级运放或低功耗 OTA</td><td>设计项目</td><td>进阶</td><td>明确负载、增益、带宽、相位裕度、摆幅与功耗，逐项验证</td></tr><tr><td>ADC / PLL 行为模型</td><td>Python 或电路级项目</td><td>进阶</td><td>比较理想模型与非理想因素，先解释趋势，再扩大复杂度</td></tr></tbody></table><p>建议报告按四部分组织：规格与假设、手算设计、仿真方法、结果与不足。直流工作点正确后再看交流和瞬态；反馈电路测环路增益要使用合适方法。进一步检查工艺、电压、温度（Process, Voltage, Temperature，PVT）与失配敏感性。完成版图后，寄生提取与后仿真可能改变结论，原理图仿真通过不是流片可用的证明。</p><h2 id="与上科大课程配合" tabindex="-1">与上科大课程配合 <a class="header-anchor" href="#与上科大课程配合" aria-label="Permalink to &quot;与上科大课程配合&quot;">​</a></h2>',12)),h(e,{codes:"EE115A,EE112,EE212,EE291I"}),t[1]||(t[1]=a('<p><a href="/shanghaitech-ic-wiki-dev.github.io/courses/ee115a">EE115A</a> 阶段优先补器件与基本放大电路；后续课程可结合 CMOS 集成电路教材深入。具体采用何种教材、模型及设计项目，以当学期大纲为准。不要把公开教材中的示例工艺参数直接当成本校实验 PDK 参数。</p><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">上科大信息学院 2026–2027 学年开课计划</a>。</li><li><a href="https://www.seas.ucla.edu/brweb/" target="_blank" rel="noreferrer">Razavi / UCLA Communication Circuits Laboratory</a>：作者教材与教学入口；其他教材可通过学校图书馆获取。</li></ul>',3))])}const C=d(n,[["render",s]]);export{f as __pageData,C as default};
